/**
 * Synthetic bench-test data for the demonstration.
 *
 * WHAT THIS IS: fabricated measurements, generated by taking the model's own prediction and
 * applying a fixed, deterministic bias plus a small repeatable wobble. It exists so the
 * measure → error → history → calibrate half of the app can be seen working without anyone
 * having to go and run a motor first.
 *
 * WHAT THIS IS NOT: evidence about any real propeller. Every generated test is stamped
 * `[DEMO DATA]` in its notes and can be cleared with one click. Nothing here is used by the
 * test suite, and no coefficient is ever fitted from it.
 *
 * The bias is deliberately chosen to reproduce the model's KNOWN weakness — over-prediction of
 * static thrust that gets worse with pitch ratio — so the history chart shows the kind of
 * systematic trend a real calibration session is looking for, rather than random scatter.
 */
import type { Battery, BenchTest, Motor, Propeller } from '../model/types';
import { calculatePropulsion } from '../model/calculatePropulsion';
import { pitchRatio } from '../model/propAero';
import { kgfToNewtons } from '../units/units';

export const DEMO_NOTE_PREFIX = '[DEMO DATA]';

/** Deterministic pseudo-random in [-1, 1] from an integer seed — no Math.random, so the demo
 *  data is identical every time it is loaded and can be diffed or reproduced. */
function wobble(seed: number): number {
  const x = Math.sin(seed * 12.9898) * 43758.5453;
  return 2 * (x - Math.floor(x)) - 1;
}

interface DemoOptions {
  motor: Motor;
  battery: Battery;
  propellers: Propeller[];
  /** ISO date of the first synthetic session; later tests are spaced a day apart. */
  startDate?: string;
}

/**
 * Generate one synthetic bench test per propeller supplied.
 *
 * The "measurement" is the prediction divided by a bias factor, so the recorded prediction
 * error comes out positive (model reads high) and grows with pitch ratio — the documented
 * failure mode of the generic coefficient model.
 */
export function generateDemoBenchTests({
  motor,
  battery,
  propellers,
  startDate = '2026-08-01T15:00:00.000Z',
}: DemoOptions): BenchTest[] {
  const t0 = new Date(startDate).getTime();
  const out: BenchTest[] = [];

  propellers.forEach((propeller, i) => {
    const predicted = calculatePropulsion({ motor, battery, propeller });
    if (!predicted.diagnostics.converged) return;

    const pr = pitchRatio(propeller);
    // Thrust bias: ~8% high at p/D = 0.4, rising to ~22% high at p/D = 0.8.
    const thrustBias = 1 + 0.08 + 0.35 * Math.max(0, pr - 0.4);
    // RPM and current are much better behaved — a couple of percent.
    const rpmBias = 1 + 0.018;
    const currentBias = 1 - 0.03;

    const jitter = (n: number, amount: number) => n * (1 + amount * wobble(i * 7 + n));

    const measuredThrustKgF = jitter(predicted.thrustKgF! / thrustBias, 0.015);
    const measuredRpm = Math.round(jitter(predicted.rpm / rpmBias, 0.008));
    const measuredCurrentA = jitter(predicted.currentA! / currentBias, 0.02);
    const measuredVoltageV = jitter(predicted.loadedVoltageV!, 0.006);

    out.push({
      id: `demo-${propeller.id}`,
      timestamp: new Date(t0 + i * 86_400_000).toISOString(),
      motorId: motor.id,
      batteryId: battery.id,
      propellerId: propeller.id,
      predicted,
      measured: {
        rpm: measuredRpm,
        thrustKgF: Number(measuredThrustKgF.toFixed(3)),
        thrustN: kgfToNewtons(measuredThrustKgF),
        currentA: Number(measuredCurrentA.toFixed(2)),
        voltageV: Number(measuredVoltageV.toFixed(2)),
      },
      notes:
        `${DEMO_NOTE_PREFIX} synthetic measurement — generated from the model with a deliberate ` +
        'pitch-dependent thrust bias. Not a real bench result.',
    });
  });

  return out;
}

export function isDemoTest(t: BenchTest): boolean {
  return (t.notes ?? '').startsWith(DEMO_NOTE_PREFIX);
}
